"""Primary-Codex transcription of three personally reviewed sources; drafts only."""
import copy, hashlib, json, re
from pathlib import Path
import sympy as s
from sympy.parsing.sympy_parser import parse_expr, standard_transformations, implicit_multiplication_application, convert_xor

ROOT=Path.cwd(); OUT=Path(__file__).parent
inventory=json.loads((ROOT/'content/planning/source-inventory.json').read_text())['sources']
canonical={q['id']:q for p in (ROOT/'content/chapters').glob('*.json') for c in json.loads(p.read_text())['categories'] for q in c['questions']}
checks=[]; records=[]
x,y,a,b,c,u,v,z,m=s.symbols('x y a b c u v z m')

def math(t):
    t=t.replace(r'\n\n','\n\n')
    def format_formula(match):
        z=match[1];depth=0;parts=[];start=0
        for i,ch in enumerate(z):
            if ch in '({[':depth+=1
            elif ch in ')}]':depth-=1
            if depth==0 and i>start and (ch in '+-=' or z[i:i+6] in [r'\times',r'\equiv'] or z[i:i+4]==r'\div'):
                parts.append(z[start:i]);start=i
            if depth==0 and ch==')' and z[i+1:i+2]=='(':
                parts.append(z[start:i+1]);start=i+1
        parts.append(z[start:]);lines=[];line=''
        for part in parts:
            if line and len(line+part)>24:
                lines.append(line);line=(r'{}\cdot' if part.startswith('(') else '')+part
            else:line+=part
        if line:lines.append(line)
        if len(lines)>1:return r'\[\begin{gathered}'+r'\\'.join(lines)+r'\end{gathered}\]'
        return r'\('+z+r'\)'
    return re.sub(r'\$(.*?)\$',format_formula,t,flags=re.S)

def begin(suffix):
    global src, records
    src=next(r for r in inventory if r['id']=='source-'+suffix)
    assert hashlib.sha256((Path('/Users/chester/Downloads/By topic Review materials')/src['path']).read_bytes()).hexdigest()==src['sha256']
    records=[]

def add(n,en,zh,sol,solzh,skill,sub,difficulty,reason,page=1,options=None,answer=None):
    q={'questionType':'mcq' if options else 'structured','assessmentMode':'automatic' if options else 'solution-comparison','difficulty':difficulty,'minForm':4,'course':'core','level':'free','subcategory':sub,'skill':skill,'stem':math(en),'stemZh':math(zh),'solution':math(sol),'solutionZh':math(solzh),'solutionStatus':'independently-rederived','source':src['path']+' · Q'+str(n),'sourceZh':src['path']+' · 第'+str(n)+'題','provenance':{'collection':'by-topic-review-materials','sourceId':src['id'],'sha256':src['sha256'],'file':src['path'],'number':str(n),'page':page,'attributionStatus':'not-supplied'},'classification':{'version':'solving-method-v1','basis':'reviewed-decisive-solving-method','status':'editor-pipeline-reviewed','difficultyReason':reason,'evidence':'docs/qa/2026-11-17/rational-wave/mathematics.json#'+src['id']+'-Q'+str(n)}}
    if options:
        q.pop('assessmentMode');q.update(options={k:math(o) for k,o in zip('ABCD',options)},optionsZh={k:math(o) for k,o in zip('ABCD',options)},answer=answer)
    for block,fields in [('contentBlocks',('stem','stemZh')),('solutionBlocks',('solution','solutionZh'))]:
        if any('\n' in q[f] for f in fields):q[block]={lang:[{'type':'paragraph','text':t} for t in q[field].split('\n\n') if t] for lang,field in zip(['en','zh-Hant'],fields)}
    records.append({'locator':str(n),'pages':[page],'disposition':'publish','category':'calculation','question':q})
    return q

def verify(n,original,result,label='simplification'):
    assert s.cancel(original-result)==0,(src['id'],n,original,result)
    checks.append({'sourceId':src['id'],'number':n,'check':label,'original':str(original),'result':str(result),'verified':True})

def rational(n,expr,exprzh,original,result,steps,stepszh,domain,domainzh,skill='poly-rational-products',difficulty='medium',options=None,answer=None,page=1):
    verify(n,original,result)
    resulttex=s.latex(s.factor(result))
    sol=steps+'\n\nThus the result is $'+resulttex+'$.\n\nKeep the original domain: '+domain+'. Cancellation does not restore excluded values.'
    zh=stepszh+'\n\n所以結果為 $'+resulttex+'$。\n\n保留原式定義域：'+domainzh+'。約去因式不能恢復原本排除的值。'
    reasons={'poly-rational-products':'Factor each numerator/denominator, invert the divisor where required, cancel factors and retain every original exclusion.','poly-rational-sums':'Factor denominators, use a common denominator, simplify the combined numerator and retain exclusions.','poly-complex-fractions':'Clear nested fractions without losing nonzero inner denominators or the original divisor condition.'}
    return add(n,'Simplify '+expr+'.','化簡 '+exprzh+'。',sol,zh,skill,'rational-expressions',difficulty,reasons[skill],page,options,answer)

def finish(name):
    (OUT/(name+'-records.json')).write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')

